function deepestLeavesSum(root) {
  let queue = [root];
  let levelSum = 0;
  while (queue.length > 0) {
    const next = [];
    levelSum = 0;
    for (const node of queue) {
      levelSum += node.val;
      if (node.left) {
        next.push(node.left);
      }
      if (node.right) {
        next.push(node.right);
      }
    }
    queue = next;
  }
  return levelSum;
}

