  const height = node => node ? 1 + Math.max(height(node.left), height(node.right)) : 0;
  const deepest = height(root);
  const total = (node, depth) => {
    if (!node) return 0;
    if (depth === deepest) return node.val;
    return total(node.left, depth + 1) + total(node.right, depth + 1);
  };
  return total(root, 1);
}

