function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 960 + pick(31) : 1 + pick(10);
  const top = size === 'large' || rand() < 0.5 ? 100 : 3;
  const chainy = rand() < 0.3;
  const nodes = [{ val: 1 + pick(top), left: null, right: null }];
  for (let i = 1; i < n; i++) {
    const node = { val: 1 + pick(top), left: null, right: null };
    for (;;) {
      const parent = chainy ? nodes[nodes.length - 1 - pick(Math.min(2, nodes.length))] : nodes[pick(nodes.length)];
      const side = rand() < 0.5 ? 'left' : 'right';
      const other = side === 'left' ? 'right' : 'left';
      if (!parent[side]) { parent[side] = node; break; }
      if (!parent[other]) { parent[other] = node; break; }
    }
    nodes.push(node);
  }
  const out = [], queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}

