function validate([root]) {
  if (root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10000 nodes.';
  if (values.some(v => v < 1 || v > 100)) return 'Each node value is between 1 and 100.';
  return null;
}
